1	import { supabase } from '../lib/supabase';
2	import { invokeFunction } from './api';
3	import { logError } from '../lib/logger';
4	import { PaymentMethodService } from './paymentMethodService';
5	
6	export interface Wallet {
7	    id: string;
8	    user_id: string;
9	    balance: number;
10	    user_type: 'company' | 'worker';
11	    asaas_customer_id?: string;
12	    created_at: string;
13	    updated_at: string;
14	}
15	
16	export interface WalletTransaction {
17	    id: string;
18	    wallet_id: string;
19	    amount: number;
20	    type: 'credit' | 'debit' | 'escrow_reserve' | 'escrow_release' | 'initial_balance' | 'platform_fee' | 'escrow_authorize';
21	    description: string | null;
22	    reference_id: string | null;
23	    created_at: string;
24	}
25	
26	export interface EscrowTransaction {
27	    id: string;
28	    job_id: string;
29	    application_id: string | null;
30	    amount: number;
31	    company_wallet_id: string;
32	    worker_wallet_id: string | null;
33	    // Postpago (Slice 2): 'authorized'/'captured' coexistem com os estados prepago.
34	    status: 'reserved' | 'authorized' | 'captured' | 'released' | 'refunded';
35	    // prepaid = pull legado (saldo); postpaid = push Slice 2 (hold no cartão). Default 'prepaid' no DB.
36	    kind?: 'prepaid' | 'postpaid';
37	    // id da cobrança no Asaas (authorizeOnly:true). NULL para prepago.
38	    asaas_payment_id?: string | null;
39	    authorized_at?: string | null;
40	    captured_at?: string | null;
41	    created_at: string;
42	    released_at: string | null;
43	    job?: { title: string };
44	}
45	
46	export const WalletService = {
47	    async getOrCreateWallet(userId: string, userType: 'company' | 'worker'): Promise<Wallet | null> {
48	        const { data: existing } = await supabase
49	            .from('wallets')
50	            .select('*')
51	            .eq('user_id', userId)
52	            .single();
53	
54	        if (existing) return existing as Wallet;
55	
56	        const { data: newWallet, error } = await supabase
57	            .from('wallets')
58	            .insert({ user_id: userId, balance: 0.00, user_type: userType })
59	            .select()
60	            .single();
61	
62	        if (error) {
63	            logError('Error creating wallet', error);
64	            return null;
65	        }
66	
67	        return newWallet as Wallet;
68	    },
69	
70	    async withdrawFunds(amount: number, pixKey: string, pixKeyType: string = 'CPF'): Promise<{ success: boolean; error?: string }> {
71	        try {
72	            await invokeFunction('asaas-withdraw', { amount, pixKey, pixKeyType });
73	            return { success: true };
74	        } catch (error: unknown) {
75	            logError('Error withdrawing funds', error);
76	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao realizar saque' };
77	        }
78	    },
79	
80	    async getBalance(userId: string): Promise<number> {
81	        const { data } = await supabase
82	            .from('wallets')
83	            .select('balance')
84	            .eq('user_id', userId)
85	            .single();
86	
87	        return data?.balance || 0;
88	    },
89	
90	    async getTransactions(userId: string): Promise<WalletTransaction[]> {
91	        const { data: wallet } = await supabase
92	            .from('wallets')
93	            .select('id')
94	            .eq('user_id', userId)
95	            .single();
96	
97	        if (!wallet) return [];
98	
99	        const { data } = await supabase
100	            .from('wallet_transactions')
101	            .select('*')
102	            .eq('wallet_id', wallet.id)
103	            .order('created_at', { ascending: false });
104	
105	        return (data || []) as WalletTransaction[];
106	    },
107	
108	    async reserveEscrow(jobId: string, amount: number, companyUserId: string): Promise<{ success: boolean; error?: string }> {
109	        try {
110	            const { error: rpcError } = await supabase.rpc('reserve_escrow', {
111	                p_job_id: jobId,
112	                p_amount: amount,
113	                p_company_user_id: companyUserId
114	            });
115	
116	            if (rpcError) {
117	                if (rpcError.message?.includes('Saldo insuficiente')) {
118	                    return { success: false, error: rpcError.message };
119	                }
120	                if (rpcError.message?.includes('Carteira nao encontrada')) {
121	                    return { success: false, error: 'Carteira nao encontrada' };
122	                }
123	                if (rpcError.code === '23505') {
124	                    return { success: false, error: 'Escrow ja existe para esta vaga' };
125	                }
126	                throw rpcError;
127	            }
128	
129	            return { success: true };
130	        } catch (error) {
131	            logError('Error reserving escrow', error);
132	            return { success: false, error: 'Erro ao reservar pagamento' };
133	        }
134	    },
135	
136	    async createDeposit(payload: { amount: number, name?: string, cpfCnpj?: string, billingType?: string }): Promise<{ paymentId?: string; invoiceUrl?: string; pixQrCodeUrl?: string; error?: string }> {
137	        try {
138	            return await invokeFunction('asaas-deposit', payload);
139	        } catch (error: unknown) {
140	            logError('Error creating deposit', error);
141	            return { error: error instanceof Error ? error.message : 'Erro ao criar deposito via Asaas' };
142	        }
143	    },
144	
145	    async syncBalance(): Promise<{ success: boolean; hasUpdates?: boolean; totalSynced?: number; message?: string; error?: string }> {
146	        try {
147	            return await invokeFunction('asaas-sync', {});
148	        } catch (error: unknown) {
149	            logError('Error syncing balance', error);
150	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao sincronizar saldo' };
151	        }
152	    },
153	
154	    async releaseEscrow(jobId: string, applicationId: string, workerUserId: string): Promise<{ success: boolean; error?: string }> {
155	        try {
156	            await invokeFunction('asaas-checkout', { jobId, applicationId, workerId: workerUserId });
157	            return { success: true };
158	        } catch (error: unknown) {
159	            logError('Error releasing escrow', error);
160	            return { success: false, error: error instanceof Error ? error.message : 'Erro ao liberar pagamento' };
161	        }
162	    },
163	
164	    async refundEscrow(jobId: string, reason?: string): Promise<{ success: boolean; error?: string }> {
165	        try {
166	            const { error: rpcError } = await supabase.rpc('refund_escrow', {
167	                p_job_id: jobId,
168	                p_reason: reason || 'Reembolso de vaga cancelada'
169	            });
170	
171	            if (rpcError) {
172	                if (rpcError.message?.includes('No reserved escrow')) {
173	                    return { success: true };
174	                }
175	                throw rpcError;
176	            }
177	
178	            return { success: true };
179	        } catch (error) {
180	            logError('Error refunding escrow', error);
181	            return { success: false, error: 'Erro ao reembolsar' };
182	        }
183	    },
184	
185	    async getJobEscrow(jobId: string): Promise<EscrowTransaction | null> {
186	        const { data } = await supabase
187	            .from('escrow_transactions')
188	            .select('*')
189	            .eq('job_id', jobId)
190	            .single();
191	
192	        return data as EscrowTransaction | null;
193	    },
194	
195	    /**
196	     * Libera ou captura o escrow dependendo do kind do turno.
197	     *
198	     * kind='prepaid' (pull legado): invoca asaas-checkout → release_escrow.
199	     * kind='postpaid' (push Slice 2): invoca asaas-capture-payment → capture_escrow_postpago.
200	     *
201	     * Este é o ponto de ramificação por kind para a empresa confirmar a conclusão do turno.
202	     * Deve substituir chamadas diretas a releaseEscrow em fluxos que podem ser postpago.
203	     *
204	     * @param jobId      UUID do turno.
205	     * @param workerId   UUID do worker.
206	     * @param escrowKind 'prepaid' | 'postpaid'. Se omitido, busca do DB.
207	     */
208	    async releaseOrCaptureEscrow(
209	      jobId: string,
210	      workerId: string,
211	      escrowKind?: 'prepaid' | 'postpaid'
212	    ): Promise<{ success: boolean; error?: string }> {
213	      try {
214	        // Se kind não foi passado, buscar do DB
215	        let kind = escrowKind;
216	        if (!kind) {
217	          const { data: escrow } = await supabase
218	            .from('escrow_transactions')
219	            .select('kind')
220	            .eq('job_id', jobId)
221	            .maybeSingle();
222	          kind = (escrow?.kind as 'prepaid' | 'postpaid' | undefined) ?? 'prepaid';
223	        }
224	
225	        if (kind === 'postpaid') {
226	          return await PaymentMethodService.capturePayment(jobId, workerId);
227	        }
228	
229	        // prepaid: fluxo legado (asaas-checkout → release_escrow)
230	        return await WalletService.releaseEscrow(jobId, '', workerId);
231	      } catch (error) {
232	        logError('walletService.releaseOrCaptureEscrow', error);
233	        return { success: false, error: 'Erro ao processar pagamento do turno.' };
234	      }
235	    },
236	
237	    async getCompanyEscrows(companyUserId: string): Promise<EscrowTransaction[]> {
238	        const { data: wallet } = await supabase
239	            .from('wallets')
240	            .select('id')
241	            .eq('user_id', companyUserId)
242	            .single();
243	
244	        if (!wallet) return [];
245	
246	        const { data } = await supabase
247	            .from('escrow_transactions')
248	            .select('*, job:jobs(title)')
249	            .eq('company_wallet_id', wallet.id)
250	            .order('created_at', { ascending: false });
251	
252	        return (data || []) as EscrowTransaction[];
253	    }
254	};
