1	import { useEffect, useState } from 'react';
2	import { useParams, useNavigate } from 'react-router-dom';
3	import { supabase } from '../../lib/supabase';
4	import { WalletService } from '../../services/walletService';
5	import { logError } from '../../lib/logger';
6	import { ArrowLeft, Star, MapPin, Clock, ChevronRight, CheckCircle, XCircle, MessageSquare, Play, Square, Loader2 } from 'lucide-react';
7	import { formatDistanceToNow } from 'date-fns';
8	import { ptBR } from 'date-fns/locale';
9	import { useToast } from '../../contexts/ToastContext';
10	import JobLifecycleStepper from '../../components/JobLifecycleStepper';
11	import EscrowStatusBadge from '../../components/EscrowStatusBadge';
12	import type { Application } from '../../types';
13	
14	export default function CompanyJobCandidates() {
15	    const { id } = useParams();
16	    const navigate = useNavigate();
17	
18	    const [candidates, setCandidates] = useState<Application[]>([]);
19	    const [jobTitle, setJobTitle] = useState('');
20	    const [loading, setLoading] = useState(true);
21	    const [ratingModalOpen, setRatingModalOpen] = useState(false);
22	    const [selectedApp, setSelectedApp] = useState<Application | null>(null);
23	    const [rating, setRating] = useState(5);
24	    const [comment, setComment] = useState('');
25	    const [submittingReview, setSubmittingReview] = useState(false);
26	    const [confirmingCheckin, setConfirmingCheckin] = useState<string | null>(null);
27	    const [companyBalance, setCompanyBalance] = useState<number | null>(null);
28	    const [confirmDeliveryApp, setConfirmDeliveryApp] = useState<Application | null>(null);
29	    const [releasing, setReleasing] = useState(false);
30	    const [escrowStatusMap, setEscrowStatusMap] = useState<Record<string, 'reserved' | 'released'>>({});
31	    const { addToast } = useToast();
32	
33	    useEffect(() => {
34	        if (id) fetchCandidates();
35	    // eslint-disable-next-line react-hooks/exhaustive-deps -- fetchCandidates usa state setters estaveis, so precisa re-executar quando id muda
36	    }, [id]);
37	
38	    const fetchCandidates = async () => {
39	        try {
40	            const { data: { user } } = await supabase.auth.getUser();
41	            if (!user) { navigate('/login'); return; }
42	
43	            // Fetch Job Title (only if owned by this company)
44	            const { data: job, error: jobError } = await supabase.from('jobs').select('title').eq('id', id).eq('company_id', user.id).single();
45	            if (jobError || !job) { navigate('/company/jobs'); return; }
46	            setJobTitle(job.title);
47	
48	            // Fetch Applications with Worker Profile (using 'workers' table now)
49	            const { data, error } = await supabase
50	                .from('applications')
51	                .select(`
52	                    *,
53	                    worker:workers(*),
54	                    worker_checkin_at,
55	                    worker_checkout_at,
56	                    company_checkin_confirmed_at,
57	                    company_checkout_confirmed_at
58	                `)
59	                .eq('job_id', id)
60	                .order('created_at', { ascending: false });
61	
62	            if (error) throw error;
63	            setCandidates(data || []);
64	
65	            // Fetch escrow status per application for this job
66	            const { data: escrowRows } = await supabase
67	                .from('escrow_transactions')
68	                .select('application_id, status')
69	                .eq('job_id', id);
70	            const statusMap: Record<string, 'reserved' | 'released'> = {};
71	            (escrowRows || []).forEach((row) => {
72	                if (row.application_id && (row.status === 'reserved' || row.status === 'released')) {
73	                    statusMap[row.application_id] = row.status;
74	                }
75	            });
76	            setEscrowStatusMap(statusMap);
77	
78	            // Fetch company balance to guard the "Contratar" button (AC-7)
79	            const wallet = await WalletService.getOrCreateWallet(user.id, 'company');
80	            setCompanyBalance(wallet ? wallet.balance : null);
81	        } catch (error) {
82	            logError('CompanyJobCandidates', error);
83	        } finally {
84	            setLoading(false);
85	        }
86	    };
87	
88	    const handleUpdateStatus = async (appId: string, newStatus: string) => {
89	        const { error } = await supabase.from('applications').update({ status: newStatus }).eq('id', appId);
90	
91	        if (error) {
92	            logError('CompanyJobCandidates: handleUpdateStatus', error);
93	            addToast('Erro ao atualizar status do candidato.', 'error');
94	            return;
95	        }
96	
97	        if (newStatus === 'hired') {
98	            addToast('Candidato contratado! O job agora está em andamento.', 'success');
99	        }
100	        fetchCandidates();
101	    };
102	
103	    const handleConfirmDelivery = async (app: Application) => {
104	        setReleasing(true);
105	        // Slice 2: ramifica por escrow.kind — postpaid captura o hold no cartao; prepaid libera escrow legado.
106	        const result = await WalletService.releaseOrCaptureEscrow(app.job_id, app.worker_id);
107	        if (!result.success) {
108	            addToast('Erro ao liberar pagamento. Tente novamente.', 'error');
109	            setReleasing(false);
110	            return;
111	        }
112	        const { error: updateError } = await supabase.from('applications').update({ status: 'completed' }).eq('id', app.id);
113	        if (updateError) {
114	            addToast('Pagamento liberado, mas houve erro ao atualizar status. Contate o suporte.', 'error');
115	            setReleasing(false);
116	            setConfirmDeliveryApp(null);
117	            fetchCandidates();
118	            return;
119	        }
120	        setConfirmDeliveryApp(null);
121	        setReleasing(false);
122	        addToast('Entrega confirmada! Pagamento liberado ao profissional.', 'success');
123	        fetchCandidates();
124	    };
125	
126	    const handleSubmitReview = async () => {
127	        if (!selectedApp) return;
128	        setSubmittingReview(true);
129	
130	        try {
131	            const { data: { user } } = await supabase.auth.getUser();
132	            if (!user) throw new Error('Not authenticated');
133	
134	            // Update Application Status to reviewed (best-effort, already completed)
135	            const { error: appError } = await supabase
136	                .from('applications')
137	                .update({ status: 'completed' })
138	                .eq('id', selectedApp.id);
139	
140	            if (appError) {
141	                logError('CompanyJobCandidates: app status update failed', appError);
142	            }
143	
144	            // Create Review (non-critical, best-effort)
145	            const { error: reviewError } = await supabase.from('reviews').insert({
146	                job_id: selectedApp.job_id,
147	                reviewer_id: user.id,
148	                reviewed_id: selectedApp.worker_id,
149	                rating: rating,
150	                comment: comment,
151	                created_at: new Date().toISOString()
152	            });
153	
154	            if (reviewError) {
155	                logError('CompanyJobCandidates: review error', reviewError);
156	                if (reviewError.code === '23505') {
157	                    addToast('Você já avaliou este profissional para este job.', 'error');
158	                } else {
159	                    addToast('Erro ao salvar avaliação. Tente novamente.', 'error');
160	                }
161	                setSubmittingReview(false);
162	                setRatingModalOpen(false);
163	                fetchCandidates();
164	                return;
165	            }
166	
167	            addToast('Avaliação enviada com sucesso!', 'success');
168	
169	            setRatingModalOpen(false);
170	            setRating(5);
171	            setComment('');
172	            fetchCandidates();
173	
174	        } catch (error) {
175	            logError('CompanyJobCandidates', error);
176	            addToast('Erro ao enviar avaliação.', 'error');
177	        } finally {
178	            setSubmittingReview(false);
179	        }
180	    };
181	
182	    const handleChat = async (app: Application) => {
183	        try {
184	            // Check if conversation exists
185	            const { data: existingConvs } = await supabase
186	                .from('Conversation')
187	                .select('id')
188	                .eq('application_uuid', app.id)
189	                .limit(1);
190	
191	            if (existingConvs && existingConvs.length > 0) {
192	                navigate(`/company/messages?conversation=${existingConvs[0].id}`);
193	            } else {
194	                // Create new conversation
195	                const newConvId = crypto.randomUUID();
196	                const { error } = await supabase
197	                    .from('Conversation')
198	                    .insert({
199	                        id: newConvId,
200	                        application_uuid: app.id,
201	                        islocked: false
202	                    });
203	
204	                if (error) throw error;
205	                navigate(`/company/messages?conversation=${newConvId}`);
206	            }
207	        } catch (error) {
208	            logError('CompanyJobCandidates', error);
209	            addToast('Erro ao iniciar conversa.', 'error');
210	        }
211	    };
212	
213	    const handleConfirmCheckin = async (appId: string) => {
214	        setConfirmingCheckin(appId);
215	        try {
216	            const { error } = await supabase
217	                .from('applications')
218	                .update({ company_checkin_confirmed_at: new Date().toISOString() })
219	                .eq('id', appId);
220	
221	            if (error) throw error;
222	            fetchCandidates();
223	        } catch (error) {
224	            logError('CompanyJobCandidates', error);
225	            addToast('Erro ao confirmar check-in.', 'error');
226	        } finally {
227	            setConfirmingCheckin(null);
228	        }
229	    };
230	
231	    const handleConfirmCheckout = async (appId: string) => {
232	        setConfirmingCheckin(appId);
233	        try {
234	            const { error } = await supabase
235	                .from('applications')
236	                .update({ company_checkout_confirmed_at: new Date().toISOString() })
237	                .eq('id', appId);
238	
239	            if (error) throw error;
240	            fetchCandidates();
241	        } catch (error) {
242	            logError('CompanyJobCandidates', error);
243	            addToast('Erro ao confirmar check-out.', 'error');
244	        } finally {
245	            setConfirmingCheckin(null);
246	        }
247	    };
248	
249	    const computeSteps = (app: Application) => {
250	        const checkinComplete = !!(app.worker_checkin_at && app.company_checkin_confirmed_at);
251	        const checkinActive = !!(app.worker_checkin_at && !app.company_checkin_confirmed_at);
252	        const checkoutComplete = !!(app.worker_checkout_at && app.company_checkout_confirmed_at);
253	        const checkoutActive = !!(app.worker_checkout_at && !app.company_checkout_confirmed_at);
254	
255	        return [
256	            { label: 'Contratado', status: 'complete' as const },
257	            {
258	                label: 'Chegada',
259	                status: checkinComplete ? 'complete' as const : checkinActive ? 'active' as const : 'pending' as const
260	            },
261	            {
262	                label: 'Saída',
263	                status: checkoutComplete ? 'complete' as const : checkoutActive ? 'active' as const : 'pending' as const
264	            },
265	            {
266	                label: 'Entrega',
267	                status: app.status === 'completed' ? 'complete' as const : 'pending' as const
268	            }
269	        ];
270	    };
271	
272	    return (
273	        <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
274	            {/* Header */}
275	            <div className="flex items-center justify-between mb-8">
276	                <div>
277	                    <button onClick={() => navigate('/company/jobs')} className="flex items-center gap-2 text-gray-400 font-bold hover:text-black transition-colors mb-2">
278	                        <ArrowLeft size={16} strokeWidth={3} /> Voltar para Vagas
279	                    </button>
280	                    <h1 className="text-3xl font-black uppercase tracking-tighter">Candidatos</h1>
281	                    <p className="text-gray-500 font-bold">{jobTitle} • {candidates.length} aplicações</p>
282	                </div>
283	            </div>
284	
285	            {/* Candidates List */}
286	            <div className="space-y-4">
287	                {loading ? (
288	                    <div className="space-y-4 animate-pulse">
289	                        {[...Array(3)].map((_, i) => (
290	                            <div key={i} className="bg-gray-200 rounded-xl h-32" />
291	                        ))}
292	                    </div>
293	                ) : candidates.length === 0 ? (
294	                    <div className="text-center py-16">
295	                        <p className="text-gray-500 text-lg font-bold">Nenhum candidato encontrado.</p>
296	                        <p className="text-gray-400 text-sm mt-2">Ainda não há candidatos para esta vaga.</p>
297	                    </div>
298	                ) : (
299	                    candidates.map((app) => (
300	                        <div key={app.id} role="button" tabIndex={0} className="bg-white border-2 border-gray-100 hover:border-black rounded-xl p-6 transition-all group hover:shadow-[4px_4px_0px_0px_rgba(0,0,0,1)] cursor-pointer" onClick={() => navigate(`/company/worker/${app.worker_id}`)} onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); navigate(`/company/worker/${app.worker_id}`); } }}>
301	                            <div className="flex flex-col md:flex-row gap-6">
302	                                {/* Avatar */}
303	                                <div className="flex-shrink-0">
304	                                    <div className="w-16 h-16 rounded-full bg-gray-200 border-2 border-black overflow-hidden relative">
305	                                        {app.worker?.avatar_url ? (
306	                                            <img src={app.worker.avatar_url} alt={app.worker.full_name} className="w-full h-full object-cover" />
307	                                        ) : (
308	                                            <div className="w-full h-full flex items-center justify-center bg-black text-white font-black text-xl">
309	                                                {app.worker?.full_name?.[0] || '?'}
310	                                            </div>
311	                                        )}
312	                                    </div>
313	                                </div>
314	
315	                                {/* Info */}
316	                                <div className="flex-1">
317	                                    <div className="flex justify-between items-start">
318	                                        <div>
